CREATE FUNCTION public.verify_ai_accounting(_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _proof IS NULL OR encode(sha256(convert_to(_proof,'UTF8')),'hex')<>'d26dfd0deb7502eb4c3f491d74ce10db48f0d2582470ce69895e92148d4b21a3' THEN RAISE EXCEPTION 'server accounting verification required'; END IF; END $$;
REVOKE ALL ON FUNCTION public.verify_ai_accounting(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.settle_ai_credits_verified(_run uuid,_actual int,_provider text,_model text,_input_tokens int,_output_tokens int,_cost_estimate_eur numeric,_proof text) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.verify_ai_accounting(_proof); RETURN public.settle_ai_credits(_run,_actual,_provider,_model,_input_tokens,_output_tokens,_cost_estimate_eur); END $$;
CREATE FUNCTION public.refund_ai_credits_verified(_run uuid,_proof text) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.verify_ai_accounting(_proof); RETURN public.refund_ai_credits(_run); END $$;
CREATE FUNCTION public.begin_coordinated_analysis_verified(_org uuid,_workspace uuid,_request uuid,_input jsonb,_proof text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.verify_ai_accounting(_proof); RETURN public.begin_coordinated_analysis(_org,_workspace,_request,_input); END $$;
CREATE FUNCTION public.finish_coordinated_analysis_verified(_id uuid,_reply text,_proof text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.verify_ai_accounting(_proof); IF _reply IS NULL THEN RAISE EXCEPTION 'analysis cannot be completed'; END IF; RETURN public.finish_coordinated_analysis(_id,_reply); END $$;
CREATE FUNCTION public.fail_coordinated_analysis_verified(_id uuid,_error text,_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.verify_ai_accounting(_proof); PERFORM public.fail_coordinated_analysis(_id,_error); END $$;
CREATE FUNCTION public.checkpoint_coordinated_analysis_verified(_id uuid,_step int,_text text,_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.verify_ai_accounting(_proof); PERFORM public.checkpoint_coordinated_analysis(_id,_step,_text); END $$;
REVOKE ALL ON FUNCTION public.settle_ai_credits(uuid,int,text,text,int,int,numeric),public.refund_ai_credits(uuid),public.begin_coordinated_analysis(uuid,uuid,uuid,jsonb),public.finish_coordinated_analysis(uuid,text),public.fail_coordinated_analysis(uuid,text),public.checkpoint_coordinated_analysis(uuid,int,text) FROM PUBLIC,anon,authenticated;
